//! The reader's stage `reader.notes-exported@1` as this plugin hears it: the
//! input that names the notes file, and the answer (`notes.done`) the reader
//! ignores. The codec is the schema's (`stages/`, generated by
//! `tools/stage-codec.py`).
use crate::stages::reader_notes_exported_v1::{NotesDone, NotesExported};
use paperpaw_sdk::native::{Error, reply::Reply};

/// The stage's id.
pub use crate::declarations::EXPORT_STAGE as STAGE;

/// The root of the user's files on the card, where the notes are read from
/// (the reader sends 1; a notes file in another root is not read).
pub const ROOT_FILES: u32 = 1;

/// The path of the notes file a run names; `None` for a file the plugin does
/// not read (another root, an empty path).
///
/// # Errors
/// [`Error::Unsupported`] for another stage; [`Error::Invalid`] for an input
/// the schema refuses.
pub fn read<'a>(stage: &str, payload: &'a [u8]) -> Result<Option<&'a str>, Error> {
    if stage != STAGE {
        return Err(Error::Unsupported);
    }
    let input = NotesExported::decode(payload).map_err(|_| Error::Invalid)?;
    if input.root != ROOT_FILES || input.path.is_empty() {
        return Ok(None);
    }
    Ok(Some(input.path))
}

/// Answers the run: `notes.done`, status 0 when the notes were taken, 1 when not.
///
/// # Errors
/// What the reply refuses.
pub fn done(reply: &mut Reply<'_>, taken: bool) -> Result<(), Error> {
    let mut out = [0; 16];
    let length = answer(taken, &mut out)?;
    reply.write(out.get(..length).ok_or(Error::Invalid)?)
}

/// The bytes of the answer; their length.
fn answer(taken: bool, out: &mut [u8]) -> Result<usize, Error> {
    NotesDone::new(Some(u32::from(!taken)))
        .encode(out)
        .map_err(|_| Error::Invalid)
}

#[cfg(test)]
mod tests {
    #![allow(clippy::unwrap_used, reason = "test assertions")]
    use super::*;

    fn input(root: u32, path: &str) -> std::vec::Vec<u8> {
        let mut out = [0; 800];
        let length = NotesExported::new(root, path, "A book")
            .encode(&mut out)
            .unwrap();
        out[..length].to_vec()
    }

    #[test]
    fn the_path_of_a_card_file_is_read() {
        let bytes = input(ROOT_FILES, "Notes/book.md");
        assert_eq!(read(STAGE, &bytes), Ok(Some("Notes/book.md")));
    }

    #[test]
    fn another_root_or_no_path_is_not_read() {
        assert_eq!(read(STAGE, &input(0, "Notes/book.md")), Ok(None));
        assert_eq!(read(STAGE, &input(ROOT_FILES, "")), Ok(None));
    }

    #[test]
    fn another_stage_or_a_broken_input_is_refused() {
        assert_eq!(
            read("core.status", &input(1, "a.md")),
            Err(Error::Unsupported)
        );
        assert_eq!(read(STAGE, &[9, 9, 9]), Err(Error::Invalid));
    }

    #[test]
    fn the_answer_is_a_notes_done_record() {
        for (taken, status) in [(true, 0), (false, 1)] {
            let mut buffer = [0; 16];
            let length = answer(taken, &mut buffer).unwrap();
            assert_eq!(
                NotesDone::decode(&buffer[..length]).unwrap().status,
                Some(status)
            );
        }
    }
}
